class Solution {
public:
    int bestTeamScore(vector<int>& scores, vector<int>& ages) {
        int n = scores.size();
        vector<pair<int,int>> players(n);
        for (int i = 0; i < n; i++) {
            players[i] = {ages[i], scores[i]};
        }
        sort(players.begin(), players.end());

        vector<int> sortedScores(scores.begin(), scores.end());
        sort(sortedScores.begin(), sortedScores.end());
        sortedScores.erase(unique(sortedScores.begin(), sortedScores.end()), sortedScores.end());
        int m = sortedScores.size();

        vector<int> bit(m + 2, 0);

        auto update = [&](int idx, int val) {
            for (; idx <= m; idx += idx & (-idx))
                bit[idx] = max(bit[idx], val);
        };

        auto query = [&](int idx) {
            int res = 0;
            for (; idx > 0; idx -= idx & (-idx))
                res = max(res, bit[idx]);
            return res;
        };

        int ans = 0;
        for (int i = 0; i < n; i++) {
            int score = players[i].second;
            int rank = lower_bound(sortedScores.begin(), sortedScores.end(), score)
                       - sortedScores.begin() + 1;
            int best = query(rank);
            int cur = best + score;
            update(rank, cur);
            ans = max(ans, cur);
        }

        return ans;
    }
};
